 const pavementMat=new THREE.MeshStandardMaterial({color:'#a69e8c',roughness:.95});for(const side of [-1,1]){const m=new THREE.Mesh(strip(t,4,side*(t.width/2+2)),pavementMat);m.position.y=.12;m.receiveShadow=true;this.scene.add(m);}
 const ground=new THREE.Mesh(new THREE.PlaneGeometry(3400,3400),new THREE.MeshStandardMaterial({color:'#6e7960',roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.set(170,-.5,30);ground.receiveShadow=true;this.scene.add(ground);
