 const eye=new V(),look=new V(player.x,player.y+.9,player.z);if(menu){const a=reducedMotion?-.7:-.7+Math.sin(this.time*.12)*.5;eye.set(player.x+Math.sin(player.heading+a)*9,player.y+3.1,player.z+Math.cos(player.heading+a)*9);}
 else{const distance=8.1+clamp(player.speed/62,0,1)*1.2,dir=rear?1:-1;eye.set(player.x+Math.sin(player.heading)*distance*dir,player.y+3.25,player.z+Math.cos(player.heading)*distance*dir);look.x+=Math.sin(player.heading)*(rear?-8:9);look.z+=Math.cos(player.heading)*(rear?-8:9);}
